/**
 * @file v90_constellation_designer.h
 * @brief V90ConstellationDesigner: designs the V.90 digital-side constellation (the six per-phase ucode lists) for a measured noise level.
 *
 * The designer belongs to the V.90 demodulator and is a plain class (no virtual functions; 0x54 bytes in the 32-bit layout checked by
 * v90_constellation_designer_layout.inc, generated by tools/layout_gen.py).  Its methods are spread over three source files:
 * - v90_constellation_dmin.cpp: construction, reset(), setMinMaxRates(), process() (the entry point), constellationDesign(), spectralDesign(),
 *   determineDminForRrn() and the small mapping helpers;
 * - v90_constellation_noise.cpp: setConstellationToNoise() and setConstellationToNoise_forceRate();
 * - v90_constellation_power.cpp: adjustConstellationsPower() and adjustConstellationsToNewK().
 *
 * From the measured noise energy the noise functions set the minimum distance dMin_ (and, per state_, the pre-decision-SNR thresholds for rate up / down /
 * retrain), then fill mapParams_->listA_ / listB_ / cnt_ with the ucode indices of each of the six phases and their G.711 codes.  The plain version
 * scans the ucodes from the parameter block's unk360 up to the per-phase maximum and keeps those whose distance exceeds a running half distance; the
 * forced-rate version distributes a requested number of ucodes over the phases (a base count scaled by 1/4 and 1/2 for the two kinds of phases and
 * adjusted until their product reaches 2^n) and iterates until every phase has its count.
 */
#ifndef DSP_CLASSES_P24_H
#define DSP_CLASSES_P24_H

#include "core/dsp_cxx.h"
#include "pcm_parameters.h"     /* V90Parameters */
#include "v92_cp.h"             /* V90MappingParams */
#include "pcm_leaf_classes.h"   /* V90ConstellationPower, PcmType, V90TxPowerMeasurementPoint (getPower / getPowerIndexForPower) */
#include "v90_adid.h"           /* V90AutoDigitalImpDetector (the linear-mapping / allowed-ucode tables and suspectedPhase_ the designer reads) */
#include "v92_echo_canceller.h" /* V90PreFilter, __tHardwareCodecTypes__ (process stores the codec type) */

/** Special spectral condition that process() / spectralDesign() branch on (same values as V90SpectralVerifier::flag_). */
enum V90SpecialSpectralConditions
{
  V90SSC_NONE = 0,        ///< no special condition
  V90SSC_ISDN = 1,        ///< ISDN line
  V90SSC_PBX = 2,         ///< PBX line: the German-PBX spectral shaper set is taken
  V90SSC_SEVERE_CODEC = 3 ///< severe codec
};

class V90ConstellationDesigner
{
public:
  /* ---- v90_constellation_dmin.cpp: construction, reset, rate window, process and the helpers ---- */
  V90ConstellationDesigner(V90Parameters* p, V90PreFilter* pf, V90ConstellationPower* pw); ///< parameter block, pre-filter and power calculator, borrowed
  ~V90ConstellationDesigner();
  void reset();                                            ///< clear the design state
  void setMinMaxRates(unsigned minRate, unsigned maxRate); ///< rate window for the next process()
  /** Design the whole constellation for a noise level and rate mask; 0 on success, 1 when D is at or below the minimum. */
  int process(unsigned lookahead, V90AutoDigitalImpDetector* adid, float noise, int rateMask, V90MappingParams* mp, short (*A)[128], short (*B)[128],
              short* dual, unsigned char* fixedU, unsigned char* cur, unsigned char powerLimit, __tHardwareCodecTypes__ codec, unsigned arg13,
              V90SpecialSpectralConditions special);
  /** One design pass (noise selection, power and redundancy adjustment); no caller in the library. */
  void constellationDesign(float noise, short (*A)[128], short (*B)[128], short* dual, unsigned char* fixedU, unsigned char* cur, unsigned char (*valid)[128]);
  void spectralDesign(unsigned lookahead, V90SpecialSpectralConditions special); ///< copy the spectral-shaper constants into the mapping block
  /* helpers on the mapping block that no other source file in the library calls */
  float pow6(short x);
  unsigned maxK(V90MappingParams* mp);
  float calcK(unsigned m, float* arr);
  unsigned char constelBuild(short dmin, short phase);
  unsigned calcMtoMatchKtarget(float a, float b);
  float realK(V90MappingParams* mp);
  int findConstelMaxValueIndex(V90MappingParams* mp);
  int findMinValueIndex(V90MappingParams* mp);
  int findNextUcodeToAdd(unsigned char* out, unsigned char phase, short (*A)[128], short (*B)[128], short* dual, unsigned char (*valid)[128]);
  void reconstructInitialConditions(V90MappingParams* mp, unsigned char* ucodes);

  /* ---- v90_constellation_power.cpp: adjust power and K ---- */
  void adjustConstellationsPower(); ///< reduce the digital power to the limit by dropping points
  /** Bring the redundancy to the target K by adding or removing points. */
  void adjustConstellationsToNewK(short (*A)[128], short (*B)[128], short* dual, unsigned char (*valid)[128]);
  /** Compute the rate-down / rate-up minimum distances (writes rrnDownDmin_ and rrnUpDmin_ only). */
  void determineDminForRrn(unsigned k);

  /* ---- v90_constellation_noise.cpp: noise-driven ucode selection ---- */
  /** Choose the ucodes of each phase for a noise level (plain version). */
  void setConstellationToNoise(float noise, short (*A)[128], short (*B)[128], short* dual, unsigned char* maxU, unsigned char (*valid)[128]);
  /** The same for a forced rate: distribute the requested number of ucodes over the phases. */
  void setConstellationToNoise_forceRate(float noise, short (*A)[128], short (*B)[128], short* dual, unsigned char* fixedU, unsigned char* cur,
                                         unsigned char (*valid)[128]);

public:
  V90Parameters* params_;           ///< parameter block, borrowed
  V90MappingParams* mapParams_;     ///< mapping block being designed, borrowed (stored by process)
  uint8_t flag8_;                   ///< process: (uint8)(42 - D), plus 1 when above 4; adjustConstellationsPower tests > 13
  uint8_t unk09_[1];                ///< unused
  int16_t dMin_;                    ///< minimum distance of the designed constellation
  int16_t rrnDownDmin_;             ///< minimum distance for one rate step down
  int16_t rrnUpDmin_;               ///< minimum distance for one rate step up
  int16_t dMinAlt_;                 ///< alternate minimum distance, trunc(1.25 * dMin_)
  uint8_t unk12_[2];                ///< unused
  V90AutoDigitalImpDetector* adid_; ///< digital impairment detector, borrowed (stored by process)
  float threshUp_;                  ///< pre-decision SNR threshold for a rate up
  float threshDown_;                ///< pre-decision SNR threshold for a rate down
  float threshRetrain_;             ///< pre-decision SNR threshold for a retrain
  uint32_t w24_;                    ///< process: first chosen rate (set while 0); reset: parameter unk39c
  uint32_t w28_;                    ///< process: adid_->pcmType_
  uint32_t useAlaw_;                ///< companding law of the codec: nonzero = A-law
  V90ConstellationPower* power_;    ///< constellation power calculator, borrowed
  uint8_t unk34_[4];                ///< unused (the pointer above is 8 bytes on x86-64: the region follows it)
  uint8_t powerLimit_;              ///< ctor 0x16; process: its powerLimit argument, the power index limit (min(powerLimit_, 22))
  uint8_t unk39_[3];                ///< unused
  uint32_t codec_;                  ///< process: its __tHardwareCodecTypes__ argument (never read)
  uint32_t w40_;                    ///< process: its thirteenth argument (never read)
  V90PreFilter* preFilter_;         ///< pre-filter, borrowed
  uint32_t state_;                  ///< design state: 0 no restriction, 1 keep rate; set to 1 by setConstellationToNoise()
  uint32_t maxRate_;                ///< highest acceptable rate in bit/s
  uint32_t minRate_;                ///< lowest acceptable rate in bit/s
};

typedef V90ConstellationDesigner P24_V90ConstellationDesigner;

#include "v90_constellation_designer_layout.inc"

#endif /* DSP_CLASSES_P24_H */
